def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))
    for r, c in blocks:
        for rr in (r, r + 1):
            for cc in (c, c + 1):
                out[rr][cc] = 2
        # Rays radiate diagonally outward from each surrounding colored corner.
        corners = [
            (r - 1, c - 1, -1, -1),
            (r - 1, c + 2, -1, 1),
            (r + 2, c - 1, 1, -1),
            (r + 2, c + 2, 1, 1),
        ]
        vals = [grid[rr][cc] if 0 <= rr < h and 0 <= cc < w else 0 for rr, cc, _, _ in corners]
        # TL receives BL's color; TR receives TL's; BL receives BR's; BR receives TR's.
        rayvals = [vals[2], vals[0], vals[3], vals[1]]
        for (rr, cc, dr, dc), color in zip(corners, rayvals):
            while 0 <= rr < h and 0 <= cc < w:
                if color:
                    out[rr][cc] = color
                rr += dr
                cc += dc
    return out
